import React, { useEffect, useRef, useState } from "react";

const GREETING_FIRST_LINE = "Happy Birthday,";
const GREETING_SECOND_LINE = "Sayangku! ♡";
const GREETING_TEXT = `${GREETING_FIRST_LINE} ${GREETING_SECOND_LINE}`;
const LETTER_TEXT = [
  "Happy birthday, sayangku! 🎂❤️",
  "Makasih ya udah hadir di hidupku. Aku bersyukur bisa kenal kamu dan punya banyak cerita bareng kamu.",
  "Di umur yang baru ini, aku harap kamu selalu sehat, bahagia, dilancarkan semua urusannya, dan dimudahkan dalam mengejar semua impianmu. Semoga hal-hal baik datang satu per satu, dan semua usaha yang kamu lakukan membawa hasil yang membanggakan.",
  "Aku harap kamu selalu punya alasan untuk tersenyum, orang-orang baik yang menemani, dan keberanian untuk mencoba hal-hal baru. Saat hari terasa berat, semoga kamu ingat bahwa kamu tidak harus menghadapi semuanya sendirian.",
  "Jangan terlalu keras sama diri sendiri, ya. Aku harap dunia selalu baik sama kamu. Terima kasih sudah menjadi tempat pulang yang nyaman dan sudah menerima aku dengan segala kurangku.",
  "Semoga kita terus punya waktu untuk tertawa, saling mendukung, dan membuat kenangan kecil yang akan selalu kita ingat. Semoga aku masih bisa nemenin kamu di banyak ulang tahun berikutnya. ♡",
  "With love,\nyour girlfriend, Wita.",
].join("\n\n");

function GiftConfetti({ active }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!active) return undefined;

    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");
    if (!canvas || !context) return undefined;

    const width = window.innerWidth;
    const height = window.innerHeight;
    const pixelRatio = Math.min(window.devicePixelRatio || 1, 1.5);
    const duration = 4350;
    const colors = ["#ff176b", "#ffcf00", "#00d9ff", "#8cff00", "#ff6b00", "#bb35ff", "#ffffff", "#00e6a8", "#ff4fc8"];

    canvas.width = width * pixelRatio;
    canvas.height = height * pixelRatio;
    context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);

    const particles = Array.from({ length: 1800 }, () => {
      return {
        x: width / 2 + (Math.random() - 0.5) * 110,
        y: height * 0.55 + (Math.random() - 0.5) * 70,
        velocityX: (Math.random() - 0.5) * width * 1.35,
        velocityY: (Math.random() - 0.68) * height * 1.5,
        gravity: 28 + Math.random() * 72,
        rotation: Math.random() * Math.PI * 2,
        spin: (Math.random() - 0.5) * 11,
        sway: 12 + Math.random() * 48,
        swayOffset: Math.random() * Math.PI * 2,
        width: 4 + Math.random() * 8,
        height: 7 + Math.random() * 16,
        delay: Math.random() * 0.3,
        lifetime: 2.9 + Math.random() * 0.85,
        color: colors[Math.floor(Math.random() * colors.length)],
        isRound: Math.random() < 0.2,
      };
    });

    const startedAt = performance.now();
    let previousFrame = startedAt;
    let animationFrame;

    const draw = (now) => {
      const elapsed = now - startedAt;
      const delta = Math.min((now - previousFrame) / 1000, 0.04);
      previousFrame = now;
      context.clearRect(0, 0, width, height);

      particles.forEach((particle) => {
        const age = elapsed / 1000 - particle.delay;
        if (age < 0 || age > particle.lifetime) return;

        particle.x += particle.velocityX * delta;
        particle.y += particle.velocityY * delta;
        particle.x += Math.sin(age * 3.2 + particle.swayOffset) * particle.sway * delta;
        particle.velocityY += particle.gravity * delta;
        particle.rotation += particle.spin * delta;

        const fadeIn = Math.min(1, age / 0.16);
        const fadeOut = Math.min(1, (particle.lifetime - age) / 1.1);
        context.globalAlpha = Math.max(0, Math.min(fadeIn, fadeOut));
        context.fillStyle = particle.color;
        context.save();
        context.translate(particle.x, particle.y);
        context.rotate(particle.rotation);

        if (particle.isRound) {
          context.beginPath();
          context.arc(0, 0, particle.width / 2, 0, Math.PI * 2);
          context.fill();
        } else {
          context.fillRect(-particle.width / 2, -particle.height / 2, particle.width, particle.height);
        }

        context.restore();
      });

      context.globalAlpha = 1;
      if (elapsed < duration) {
        animationFrame = window.requestAnimationFrame(draw);
      }
    };

    animationFrame = window.requestAnimationFrame(draw);

    return () => {
      window.cancelAnimationFrame(animationFrame);
      context.clearRect(0, 0, width, height);
    };
  }, [active]);

  return <canvas className="gift-gate__confetti" ref={canvasRef} aria-hidden="true" />;
}

function BackgroundFireworks({ active }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!active) return undefined;

    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");
    if (!canvas || !context) return undefined;

    const width = window.innerWidth;
    const height = window.innerHeight;
    const pixelRatio = Math.min(window.devicePixelRatio || 1, 1.5);
    const colors = ["#ff3b81", "#ffc928", "#37d9f5", "#a4e65b", "#bd72ed", "#ffffff"];

    canvas.width = width * pixelRatio;
    canvas.height = height * pixelRatio;
    context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);

    const createBurst = (startedAt) => {
      const x = width * (0.12 + Math.random() * 0.76);
      const y = height * (0.12 + Math.random() * 0.7);
      const color = colors[Math.floor(Math.random() * colors.length)];
      const particles = Array.from({ length: 48 + Math.floor(Math.random() * 28) }, () => {
        const angle = Math.random() * Math.PI * 2;
        const speed = 45 + Math.random() * 115;

        return {
          x,
          y,
          velocityX: Math.cos(angle) * speed,
          velocityY: Math.sin(angle) * speed,
          gravity: 18 + Math.random() * 28,
          size: 1.5 + Math.random() * 2.5,
          life: 1.25 + Math.random() * 0.65,
          color: Math.random() < 0.18 ? "#fff8d6" : color,
        };
      });

      return { startedAt, particles };
    };

    const startedAt = performance.now();
    let previousFrame = startedAt;
    let nextBurstAt = startedAt + 400;
    let bursts = [createBurst(startedAt)];
    let animationFrame;

    const draw = (now) => {
      const delta = Math.min((now - previousFrame) / 1000, 0.04);
      previousFrame = now;
      context.clearRect(0, 0, width, height);

      if (now >= nextBurstAt) {
        bursts.push(createBurst(now));
        nextBurstAt = now + 850 + Math.random() * 1050;
      }

      bursts = bursts.filter((burst) => now - burst.startedAt < 2100);
      bursts.forEach((burst) => {
        const age = (now - burst.startedAt) / 1000;
        burst.particles.forEach((particle) => {
          if (age >= particle.life) return;

          particle.velocityX *= Math.pow(0.985, delta * 60);
          particle.velocityY = particle.velocityY * Math.pow(0.985, delta * 60) + particle.gravity * delta;
          particle.x += particle.velocityX * delta;
          particle.y += particle.velocityY * delta;

          context.globalAlpha = Math.min(0.78, (particle.life - age) * 0.65);
          context.strokeStyle = particle.color;
          context.fillStyle = particle.color;
          context.shadowColor = particle.color;
          context.shadowBlur = 7;
          context.lineWidth = particle.size;
          context.beginPath();
          context.moveTo(particle.x - particle.velocityX * 0.025, particle.y - particle.velocityY * 0.025);
          context.lineTo(particle.x, particle.y);
          context.stroke();
          context.beginPath();
          context.arc(particle.x, particle.y, particle.size * 0.8, 0, Math.PI * 2);
          context.fill();
        });
      });

      context.globalAlpha = 1;
      context.shadowBlur = 0;
      animationFrame = window.requestAnimationFrame(draw);
    };

    animationFrame = window.requestAnimationFrame(draw);

    return () => {
      window.cancelAnimationFrame(animationFrame);
      context.clearRect(0, 0, width, height);
    };
  }, [active]);

  return <canvas className="background-fireworks" ref={canvasRef} aria-hidden="true" />;
}

export default function BfProjectBirthday() {
    const [letterOpen, setLetterOpen] = useState(false);
    const [candlesOff, setCandlesOff] = useState(false);
    const [pin, setPin] = useState("");
    const [pinError, setPinError] = useState(false);
    const [hasAccess, setHasAccess] = useState(false);
    const [giftOpened, setGiftOpened] = useState(false);
    const [giftBurstDone, setGiftBurstDone] = useState(false);
    const [slideIndex, setSlideIndex] = useState(0);
    const [typedCharacters, setTypedCharacters] = useState(0);
    const [typedLetterCharacters, setTypedLetterCharacters] = useState(0);
    const [musicTracks, setMusicTracks] = useState([]);
    const [musicIndex, setMusicIndex] = useState(0);

  const birthdayWishes = [
    { icon: "✿", title: "Hari yang lebih tenang", text: "Semoga kamu selalu sehat, bahagia, dan punya waktu untuk hal-hal yang membuatmu tersenyum." },
    { icon: "✧", title: "Mimpi yang semakin dekat", text: "Semoga setiap usaha kecil membawamu selangkah lebih dekat ke semua impianmu." },
    { icon: "♡", title: "Selalu dikelilingi cinta", text: "Semoga kamu selalu ditemani orang-orang baik yang siap mendengarkan dan mendukungmu." },
    { icon: "❀", title: "Kenangan baru bersama", text: "Semoga tahun ini penuh tawa, kejutan manis, dan banyak cerita indah untuk kita." },
  ];

  const memories = [
    { image: "image1.jpeg", alt: "Kenangan foto bersama" },
    { image: "image2.jpeg", alt: "Momen manis bersama" },
    { image: "image3.jpeg", alt: "Kolase foto photobooth berdua", centered: true },
    { image: "image4.jpeg", alt: "Bermain gokart bersama" },
    { image: "image5.jpeg", alt: "Foto berdua di depan cermin" },
    { image: "image6.jpeg", alt: "Kenangan bersama di arena permainan" },
    { image: "image7.jpeg", alt: "Foto berdua di cermin" },
    { image: "image8.jpeg", alt: "Foto-foto kenangan masa kecil", centered: true },
  ];

  const hearts = Array.from({ length: 18 }, (_, i) => i);
  const touchStartX = useRef(null);
  const musicUrls = useRef([]);

  useEffect(() => () => {
    musicUrls.current.forEach((url) => URL.revokeObjectURL(url));
  }, []);

  const addMusicTracks = (event) => {
    const addedTracks = Array.from(event.target.files || []).map((file) => ({
      title: file.name.replace(/\.[^.]+$/, ""),
      url: URL.createObjectURL(file),
    }));

    musicUrls.current.push(...addedTracks.map((track) => track.url));
    setMusicTracks((currentTracks) => [...currentTracks, ...addedTracks]);
    event.target.value = "";
  };

  useEffect(() => {
    if (!letterOpen) {
      setTypedLetterCharacters(0);
      return undefined;
    }

    let characterCount = 0;
    let typingTimeout;
    const typeNextCharacter = () => {
      characterCount += 1;
      setTypedLetterCharacters(characterCount);

      if (characterCount >= LETTER_TEXT.length) return;

      const typedCharacter = LETTER_TEXT[characterCount - 1];
      const pause = ".!?".includes(typedCharacter) ? 120 : ",;".includes(typedCharacter) ? 55 : 16;
      typingTimeout = window.setTimeout(typeNextCharacter, pause);
    };

    typingTimeout = window.setTimeout(typeNextCharacter, 180);
    return () => window.clearTimeout(typingTimeout);
  }, [letterOpen]);

  useEffect(() => {
    if (!giftBurstDone || slideIndex !== 0) return undefined;

    setTypedCharacters(0);
    let characterCount = 0;
    const typingInterval = window.setInterval(() => {
      characterCount += 1;
      setTypedCharacters(characterCount);
      if (characterCount >= GREETING_TEXT.length) {
        window.clearInterval(typingInterval);
      }
    }, 110);

    return () => window.clearInterval(typingInterval);
  }, [giftBurstDone, slideIndex]);

  const enterPinDigit = (digit) => {
    if (pin.length >= 6) return;

    const nextPin = pin + digit;
    setPinError(false);
    setPin(nextPin);

    if (nextPin.length === 6) {
      if (nextPin === "210126") {
        setHasAccess(true);
      } else {
        setPin("");
        setPinError(true);
      }
    }
  };

  const handleKeypadKeyDown = (event) => {
    if (/^\d$/.test(event.key)) {
      event.preventDefault();
      enterPinDigit(event.key);
    } else if (event.key === "Backspace") {
      event.preventDefault();
      setPin((currentPin) => currentPin.slice(0, -1));
      setPinError(false);
    } else if (event.key === "Escape") {
      setPin("");
      setPinError(false);
    }
  };

  if (!hasAccess) {
    return (
      <main className="pin-gate">
        <section className="pin-gate__content" aria-labelledby="pin-title">
          <h1 id="pin-title">For You, My Love</h1>
          <p className="pin-gate__description">
            Enter the Date we started dating as the login PIN.
          </p>

          <div
            className="pin-gate__keypad-wrap"
            onKeyDown={handleKeypadKeyDown}
          >
            <div
              className="pin-gate__indicators"
              role="status"
              aria-label={`${pin.length} dari 6 angka dimasukkan`}
            >
              {Array.from({ length: 6 }, (_, index) => (
                <span
                  className={`pin-gate__indicator${index < pin.length ? " is-filled" : ""}`}
                  key={index}
                />
              ))}
            </div>

            {pinError && (
              <p className="pin-gate__error" role="alert">
                PIN belum tepat. Coba lagi, ya.
              </p>
            )}

            <div className="pin-gate__keypad" aria-label="Papan ketik PIN">
              {["1", "2", "3", "4", "5", "6", "7", "8", "9"].map((digit, index) => (
                <button
                  autoFocus={index === 0}
                  className="pin-gate__key"
                  key={digit}
                  onClick={() => enterPinDigit(digit)}
                  type="button"
                >
                  {digit}
                </button>
              ))}
              <button
                className="pin-gate__key pin-gate__key--utility"
                onClick={() => {
                  setPin("");
                  setPinError(false);
                }}
                type="button"
              >
                Hapus
              </button>
              <button
                className="pin-gate__key"
                onClick={() => enterPinDigit("0")}
                type="button"
              >
                0
              </button>
              <button
                aria-label="Hapus angka terakhir"
                className="pin-gate__key pin-gate__key--utility"
                onClick={() => {
                  setPin((currentPin) => currentPin.slice(0, -1));
                  setPinError(false);
                }}
                type="button"
              >
                ⌫
              </button>
            </div>
          </div>
        </section>
      </main>
    );
  }

  return (
    <>
      <GiftConfetti active={giftOpened} />
      {!giftBurstDone ? (
      <main className={`gift-gate${giftOpened ? " is-open" : ""}`}>
        <section className="gift-gate__content" aria-labelledby="gift-title">
          <p className="eyebrow">A LITTLE SURPRISE FOR YOU</p>
          <h1 id="gift-title">Ada hadiah untukmu</h1>
          <button
            aria-label="Ketuk kotak kado untuk membuka hadiah"
            className={`gift-box${giftOpened ? " is-open" : ""}`}
            disabled={giftOpened}
            onClick={() => {
              setGiftOpened(true);
              window.setTimeout(() => setGiftBurstDone(true), 750);
            }}
            type="button"
          >
            <span className="gift-box__bow" />
            <span className="gift-box__body" />
            <span className="gift-box__lid" />
          </button>
          <p className="gift-gate__hint" aria-live="polite">
            {giftOpened ? "BOOM! ♡" : "Ketuk kadonya untuk membuka ♡"}
          </p>
        </section>
      </main>
      ) : (
    <main className="birthday">
      <BackgroundFireworks active={giftBurstDone} />
      <div className="floating-hearts">
        {hearts.map((heart) => (
          <span
            key={heart}
            style={{
              left: `${(heart * 37) % 100}%`,
              animationDelay: `${(heart % 8) * 0.8}s`,
              fontSize: `${14 + (heart % 4) * 5}px`,
            }}
          >
            {heart % 2 === 0 ? "♡" : "♥"}
          </span>
        ))}
      </div>

      <div
        className="slide-window"
        onKeyDown={(event) => {
          if (event.key === "ArrowLeft") {
            setSlideIndex((current) => Math.max(0, current - 1));
          } else if (event.key === "ArrowRight") {
            setSlideIndex((current) => Math.min(3, current + 1));
          }
        }}
        onTouchStart={(event) => {
          touchStartX.current = event.changedTouches[0].clientX;
        }}
        onTouchEnd={(event) => {
          if (touchStartX.current === null) return;
          const distance = event.changedTouches[0].clientX - touchStartX.current;
          if (Math.abs(distance) > 55) {
            setSlideIndex((current) => Math.max(0, Math.min(3, current + (distance < 0 ? 1 : -1))));
          }
          touchStartX.current = null;
        }}
      >
        <div className="slide-track" style={{ "--slide-index": slideIndex }}>
      <section className="hero birthday-slide" id="home" aria-label="Ucapan ulang tahun" aria-hidden={slideIndex !== 0}>
        <div className="hero-text">
          <p className="eyebrow">A SPECIAL DAY FOR SOMEONE SPECIAL</p>
          <h1 aria-label={GREETING_TEXT}>
            <span className="greeting-first-line">
              {GREETING_TEXT.slice(0, Math.min(typedCharacters, GREETING_FIRST_LINE.length))}
              {typedCharacters <= GREETING_FIRST_LINE.length && typedCharacters < GREETING_TEXT.length && <i className="typing-caret" />}
            </span>
            <br />
            <span>
              {typedCharacters > GREETING_FIRST_LINE.length && GREETING_TEXT.slice(GREETING_FIRST_LINE.length + 1, typedCharacters)}
              {typedCharacters > GREETING_FIRST_LINE.length && typedCharacters < GREETING_TEXT.length && <i className="typing-caret" />}
            </span>
          </h1>
          <p className="subtitle">
            Semoga harimu dipenuhi cinta, tawa, dan semua hal baik.
          </p>

          <div className="music-player">
            <div className="music-player__header">
              <span className="music-player__note" aria-hidden="true">♫</span>
              <div className="music-player__track-info">
                <span>OUR PLAYLIST</span>
                <strong>{musicTracks[musicIndex]?.title || "Musik untuk kita"}</strong>
              </div>
              <label className="music-player__add">
                Tambah musik
                <input
                  accept="audio/*"
                  aria-label="Tambah file musik"
                  multiple
                  onChange={addMusicTracks}
                  type="file"
                />
              </label>
            </div>

            {musicTracks.length > 0 ? (
              <>
                <div className="music-player__transport">
                  <button
                    aria-label="Putar lagu sebelumnya"
                    disabled={musicTracks.length < 2}
                    onClick={() => setMusicIndex((musicIndex - 1 + musicTracks.length) % musicTracks.length)}
                    type="button"
                  >
                    ‹
                  </button>
                  <audio
                    controls
                    key={musicTracks[musicIndex].url}
                    onEnded={() => setMusicIndex((current) => (current + 1) % musicTracks.length)}
                    src={musicTracks[musicIndex].url}
                  />
                  <button
                    aria-label="Putar lagu berikutnya"
                    disabled={musicTracks.length < 2}
                    onClick={() => setMusicIndex((musicIndex + 1) % musicTracks.length)}
                    type="button"
                  >
                    ›
                  </button>
                </div>
                <div className="music-player__playlist" aria-label="Daftar musik">
                  {musicTracks.map((track, index) => (
                    <button
                      aria-current={musicIndex === index ? "true" : undefined}
                      className={musicIndex === index ? "is-active" : ""}
                      key={track.url}
                      onClick={() => setMusicIndex(index)}
                      type="button"
                    >
                      <span>{String(index + 1).padStart(2, "0")}</span>
                      {track.title}
                    </button>
                  ))}
                </div>
              </>
            ) : (
              <p className="music-player__empty">Belum ada lagu</p>
            )}
          </div>
        </div>

        <div className="cake-area">
          <div className="sparkle sparkle-one">✦</div>
          <div className="sparkle sparkle-two">✧</div>
          <span className="cake-flower-sticker" aria-hidden="true">💐</span>
          <div
            className={`cake${candlesOff ? " is-out" : ""}`}
            role="img"
            aria-label={candlesOff ? "Kue dengan lilin yang sudah padam" : "Kue dengan lilin menyala"}
          >
            <div className="cake__candles" aria-hidden="true">
              {[0, 1, 2].map((candle) => (
                <span className="cake__candle" key={candle}>
                  <i className="cake__flame" />
                  {candlesOff && <i className="cake__smoke" />}
                </span>
              ))}
            </div>
            <div className="cake__body" aria-hidden="true" />
            <div className="cake__plate" aria-hidden="true" />
          </div>
          <div className="cake-caption">
            {candlesOff
              ? "wish made! ✨"
              : "make a wish, birthday boy ♡"}
          </div>
          <button
            className="wish-button"
            onClick={() => setCandlesOff(!candlesOff)}
          >
            {candlesOff ? "Light the candles 🕯️" : "Blow the candles ✨"}
          </button>
        </div>
      </section>

      <section className="letter-section section birthday-slide" id="letter" aria-label="A Letter From My Heart" aria-hidden={slideIndex !== 1}>
        {!letterOpen ? (
          <>
            <div className="letter-decoration">💌</div>
            <p className="eyebrow">A LETTER FROM MY HEART</p>
            <h2>To My Birthday Boy</h2>
            <p className="section-desc">
              There is something I want you to know...
            </p>
            <button
              className="main-button"
              onClick={() => setLetterOpen(true)}
            >
              Read my letter 💌
            </button>
          </>
        ) : (
          <article className="love-letter" aria-label="Isi surat ulang tahun">
            {LETTER_TEXT.slice(0, typedLetterCharacters)
              .split("\n\n")
              .filter(Boolean)
              .map((paragraph, index) => (
                <p className={index === 6 ? "letter-sign" : ""} key={index}>
                  {paragraph}
                </p>
              ))}
            {typedLetterCharacters < LETTER_TEXT.length && (
              <i className="typing-caret letter-caret" aria-hidden="true" />
            )}
          </article>
        )}
        </section>

        <section className="memories section birthday-slide" id="memories" aria-label="Our Little Memories" aria-hidden={slideIndex !== 2}>
          <p className="eyebrow">LITTLE THINGS, BIG LOVE</p>
          <h2>Our Little Memories</h2>
          <p className="section-desc">
            Every little moment with you means so much to me.
          </p>

          <div className="memory-grid">
            {memories.map((memory, index) => (
              <article
                className={`memory-card card-${index + 1}${slideIndex === 2 ? " is-visible" : ""}`}
                key={memory.image}
                style={{ "--memory-delay": `${index * 0.13}s` }}
              >
                <span className="memory-flower-sticker" aria-hidden="true">
                  {["🌷", "🌸", "💐", "🌼", "🌺", "🌷", "🌸", "💐"][index]}
                </span>
                <div className="memory-card__float">
                  <div className={`memory-image${memory.centered ? " memory-image--centered" : ""}`}>
                    <img src={`/image/${memory.image}`} alt={memory.alt} />
                  </div>
                </div>
              </article>
            ))}
          </div>
        </section>

        <section className="birthday-wishes section birthday-slide" id="wishes" aria-label="Harapan ulang tahun" aria-hidden={slideIndex !== 3}>
          <p className="eyebrow">A LITTLE WISH FOR YOUR NEW CHAPTER</p>
          <h2>Harapan Kecil Untukmu</h2>
          <p className="section-desc">Semoga tahun barumu dipenuhi banyak hal baik.</p>
          <div className="birthday-wishes__grid">
            {birthdayWishes.map((wish, index) => (
              <article
                className={`birthday-wish${slideIndex === 3 ? " is-visible" : ""}`}
                key={wish.title}
                style={{ "--wish-delay": `${index * 0.14}s` }}
              >
                <span aria-hidden="true">{wish.icon}</span>
                <h3>{wish.title}</h3>
                <p>{wish.text}</p>
              </article>
            ))}
          </div>
        </section>

        </div>
      </div>

      <div className="slide-controls">
        <button
          aria-label={["Buka surat", "Lihat memories", "Baca harapan", "Kembali ke ucapan"][slideIndex]}
          onClick={() => setSlideIndex((current) => (current + 1) % 4)}
          type="button"
        >
          {["Buka surat", "Lihat memories", "Baca harapan", "Kembali ke ucapan"][slideIndex]} ♡
        </button>
      </div>
    </main>
      )}
    </>
  );
}
